DB_BACKUP=BACKUPS/f"phocap_before_v12_student_reconciliation_{STAMP}.db"
REPORT=EXPORTS/f"bao_cao_cai_v12_nguon_hoc_sinh_doi_chieu_{STAMP}.txt"
ORIGINAL_HASHES={'app/main.py': 'f21a1f8fbe236290e9c7ae74112f7a31bd87036eb5f5a3f2d25f2aa5e6f550c9', 'app/access_control.py': 'a7623410e0d9367aa8330a3b23554818b01751d5e85098d9fc4e1a49f2098089', 'app/routers/student_survey_comparison.py': '9376cce93a6ccce5a13c1904a43df9f9a8544096c83ea88fc1f4e2e94a361293', 'app/templates/partials/dropdown_menu_v1.html': 'afc18d766aec406fa49f837d34471437964388fbc2c907b1a7e3e97d95990f11', 'app/templates/surveys/student_survey_comparison.html': 'c96cd7367a0d4365f985fbd1a7a1215fd82aaa71ef7657b37cbdf7c64b8af8bf'}
PATCHED_HASHES={'app/main.py': '7a26eeced939a142692ec165f98ca5a71fb3ec10392c68c2d62e54a81fee7a3e', 'app/access_control.py': 'a7cee182df3b80e77729d1f98232e97c7bee0a1bae2b70ff701afaa517737e2c', 'app/routers/student_survey_comparison.py': '00cc0474685efb5155007bf1ab4b62f48b8a04d89a15e721354e743404a22a08', 'app/templates/partials/dropdown_menu_v1.html': '844ee6858e19d67f205a6e4795a5b63f78f683308b273d5824abdea74a1a5802', 'app/templates/surveys/student_survey_comparison.html': 'bbd5eff3ef028b8ef64913b0c996152f8ac6d6f4883035cf981ec1ca88d6d83c', 'app/routers/student_reconciliation_source.py': 'a90019d43ea1e0c2e33dcfac443ac1b655e0476dc1aa0bd5a444855d6490192b', 'app/templates/surveys/student_reconciliation_source.html': 'd1c2204a5967a773f6ef0d9f7b09cb1e0ee4d782e4ae747b1893d8fcf3c9adbd'}
PAYLOADS={'app/main.py': '', 'app/access_control.py': '', 'app/routers/student_survey_comparison.py': '', 'app/templates/partials/dropdown_menu_v1.html': '', 'app/templates/surveys/student_survey_comparison.html': '', 'app/routers/student_reconciliation_source.py': '', 'app/templates/surveys/student_reconciliation_source.html': ''}
NEW_FILES={"app/routers/student_reconciliation_source.py","app/templates/surveys/student_reconciliation_source.html"}
RUNTIME_SCRIPT="from app.main import app\nrequired = {\n    ('/dieu-tra/nguon-hoc-sinh-doi-chieu', 'GET'),\n    ('/dieu-tra/nguon-hoc-sinh-doi-chieu/xem-truoc', 'POST'),\n    ('/dieu-tra/nguon-hoc-sinh-doi-chieu/nap', 'POST'),\n    ('/dieu-tra/nguon-hoc-sinh-doi-chieu/khoa', 'POST'),\n    ('/dieu-tra/nguon-hoc-sinh-doi-chieu/mo-khoa', 'POST'),\n}\nactual=set()\nfor r in app.router.routes:\n    p=getattr(r,'path','')\n    for m in getattr(r,'methods',set()) or set():\n        actual.add((p,m))\nmissing=sorted(required-actual)\nif missing:\n    raise SystemExit('THIEU ROUTE: '+repr(missing))\nprint('ROUTE_CHECK_PASS')\n"
REPORT_TEMPLATE='V12 CHÍNH THỨC - CÀI THÀNH CÔNG\nThời gian: {STAMP}\n\nBACKUP DB: {DB_BACKUP}\nBACKUP SOURCE: {FILE_BACKUP}\n\nDB integrity: {integrity}\nDB FK errors: {fk_count}\nV12 tables: {counts}\n\nĐÃ CÀI:\n- Menu 2.5.0 Nạp nguồn học sinh theo xã/phường.\n- ADMIN/SO/XA: xem trước -> nạp -> khóa nguồn.\n- ADMIN/SO: mở khóa nguồn.\n- Đối chiếu 2.5.1 dùng năm nguồn liền trước và chỉ dùng nguồn đã KHÓA.\n- Hiểu source->target QĐ3805 khi so trường.\n- Không so class_id giữa hai năm.\n- Không nạp dữ liệu học sinh tự động trong lúc cài.\n\nBƯỚC TIẾP:\n1. Khởi động lại Uvicorn.\n2. Vào 2. Điều tra -> 2.5 -> 2.5.0.\n3. Chọn năm đối chiếu 2026-2027, xã Nghi Lộc.\n4. Nạp lần lượt file MN/TH/THCS hoặc file tổng hợp.\n5. Kiểm tra trước, NẠP, sau đó KHÓA nguồn.\n6. Mở 2.5.1 để đối chiếu.\n'

SCHEMA_SQL=r"""
CREATE TABLE IF NOT EXISTS student_reconciliation_source_states (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 target_school_year_id INTEGER NOT NULL,
 source_school_year_id INTEGER NOT NULL,
 commune_id INTEGER NOT NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
 file_name VARCHAR(255), total_rows INTEGER NOT NULL DEFAULT 0, valid_rows INTEGER NOT NULL DEFAULT 0,
 student_count INTEGER NOT NULL DEFAULT 0, enrollment_count INTEGER NOT NULL DEFAULT 0,
 class_count INTEGER NOT NULL DEFAULT 0, import_count INTEGER NOT NULL DEFAULT 0,
 last_imported_at DATETIME, imported_by_user_id INTEGER, locked_at DATETIME, locked_by_user_id INTEGER,
 notes TEXT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL,
 CONSTRAINT uq_student_reconciliation_source_state UNIQUE(target_school_year_id,commune_id),
 FOREIGN KEY(target_school_year_id) REFERENCES school_years(id),
 FOREIGN KEY(source_school_year_id) REFERENCES school_years(id),
 FOREIGN KEY(commune_id) REFERENCES communes(id),
 FOREIGN KEY(imported_by_user_id) REFERENCES users(id),
 FOREIGN KEY(locked_by_user_id) REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS student_reconciliation_import_logs (
 id INTEGER PRIMARY KEY AUTOINCREMENT, state_id INTEGER NOT NULL, file_name VARCHAR(255) NOT NULL,
 file_sha256 VARCHAR(64) NOT NULL, total_rows INTEGER NOT NULL DEFAULT 0, valid_rows INTEGER NOT NULL DEFAULT 0,
 inserted_students INTEGER NOT NULL DEFAULT 0, updated_students INTEGER NOT NULL DEFAULT 0,
 inserted_classes INTEGER NOT NULL DEFAULT 0, inserted_enrollments INTEGER NOT NULL DEFAULT 0,
 skipped_rows INTEGER NOT NULL DEFAULT 0, warning_rows INTEGER NOT NULL DEFAULT 0, error_rows INTEGER NOT NULL DEFAULT 0,
 actor_user_id INTEGER, actor_name_snapshot VARCHAR(200), created_at DATETIME NOT NULL,
 FOREIGN KEY(state_id) REFERENCES student_reconciliation_source_states(id) ON DELETE CASCADE,
 FOREIGN KEY(actor_user_id) REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS student_reconciliation_state_enrollments (
 state_id INTEGER NOT NULL, enrollment_id INTEGER NOT NULL, PRIMARY KEY(state_id,enrollment_id),
 CONSTRAINT uq_student_reconciliation_owned_enrollment UNIQUE(enrollment_id),
 FOREIGN KEY(state_id) REFERENCES student_reconciliation_source_states(id) ON DELETE CASCADE,
 FOREIGN KEY(enrollment_id) REFERENCES student_enrollments(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_student_reconciliation_source_states_target_year ON student_reconciliation_source_states(target_school_year_id);
CREATE INDEX IF NOT EXISTS ix_student_reconciliation_source_states_source_year ON student_reconciliation_source_states(source_school_year_id);
CREATE INDEX IF NOT EXISTS ix_student_reconciliation_source_states_commune ON student_reconciliation_source_states(commune_id);
CREATE INDEX IF NOT EXISTS ix_student_reconciliation_source_states_status ON student_reconciliation_source_states(status);
CREATE INDEX IF NOT EXISTS ix_student_reconciliation_import_logs_state ON student_reconciliation_import_logs(state_id);
"""

def sha256(path:Path)->str:
 h=hashlib.sha256()
 with path.open("rb") as f:
  for chunk in iter(lambda:f.read(1024*1024),b""): h.update(chunk)
 return h.hexdigest()

def backup_database():
 BACKUPS.mkdir(parents=True,exist_ok=True)
 s=sqlite3.connect(str(DB)); d=sqlite3.connect(str(DB_BACKUP))
 try: s.backup(d); d.commit()
 finally: d.close(); s.close()
 c=sqlite3.connect(str(DB_BACKUP))
 try:
  integrity=c.execute("PRAGMA integrity_check").fetchone()[0]; fk=c.execute("PRAGMA foreign_key_check").fetchall()
  if integrity!="ok" or fk: raise RuntimeError(f"Backup DB không đạt: integrity={integrity}, FK={len(fk)}")
 finally: c.close()

def restore_database():
 if not DB_BACKUP.exists(): return
 s=sqlite3.connect(str(DB_BACKUP)); d=sqlite3.connect(str(DB))
 try: s.backup(d); d.commit()
 finally: d.close(); s.close()

def preflight_source():
 if not PROJECT.exists(): raise RuntimeError(f"Không tìm thấy dự án: {PROJECT}")
 if not DB.exists(): raise RuntimeError(f"Không tìm thấy database: {DB}")
 problems=[]
 for rel,expected_original in ORIGINAL_HASHES.items():
  path=PROJECT/rel
  if not path.exists(): problems.append(f"Thiếu file: {rel}"); continue
  current=sha256(path); expected_patched=PATCHED_HASHES[rel]
  if current not in {expected_original,expected_patched}: problems.append(f"Source đã khác gói 17:59: {rel}\n current={current}\n expected={expected_original}")
 for rel in NEW_FILES:
  path=PROJECT/rel
  if path.exists() and sha256(path)!=PATCHED_HASHES[rel]: problems.append(f"File V12 đã tồn tại nhưng khác nội dung: {rel}")
 if problems: raise RuntimeError("\n".join(problems))
 c=sqlite3.connect(str(DB))
 try:
  integrity=c.execute("PRAGMA integrity_check").fetchone()[0]; fk=c.execute("PRAGMA foreign_key_check").fetchall()
  if integrity!="ok" or fk: raise RuntimeError(f"DB preflight không đạt: integrity={integrity}, FK={len(fk)}")
 finally: c.close()

def backup_files():
 manifest=[]; FILE_BACKUP.mkdir(parents=True,exist_ok=False)
 for rel in PAYLOADS:
  src=PROJECT/rel; existed=src.exists(); manifest.append({"path":rel,"existed":existed})
  if existed:
   dst=FILE_BACKUP/rel; dst.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(src,dst)
 (FILE_BACKUP/"manifest.json").write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding="utf-8")
 return manifest

def restore_files(manifest):
 for item in reversed(manifest):
  target=PROJECT/item["path"]
  if item["existed"]:
   src=FILE_BACKUP/item["path"]
   if src.exists(): target.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(src,target)
  elif target.exists(): target.unlink()

def write_payloads():
 for rel,encoded in PAYLOADS.items():
  target=PROJECT/rel; target.parent.mkdir(parents=True,exist_ok=True); data=base64.b64decode(encoded)
  tmp=target.with_name(target.name+".v12tmp"); tmp.write_bytes(data); os.replace(tmp,target)
  actual=sha256(target)
  if actual!=PATCHED_HASHES[rel]: raise RuntimeError(f"SHA sau ghi không khớp: {rel}")

def migrate_database():
 c=sqlite3.connect(str(DB))
 try:
  c.execute("PRAGMA foreign_keys=ON"); c.executescript(SCHEMA_SQL); c.commit()
 except Exception: c.rollback(); raise
 finally: c.close()

def verify_source_syntax():
 py_files=[PROJECT/"app/main.py",PROJECT/"app/access_control.py",PROJECT/"app/routers/student_survey_comparison.py",PROJECT/"app/routers/student_reconciliation_source.py"]
 for path in py_files:
  ast.parse(path.read_text(encoding="utf-8-sig")); py_compile.compile(str(path),doraise=True)
 from jinja2 import Environment,FileSystemLoader
 env=Environment(loader=FileSystemLoader(str(PROJECT/"app/templates")))
 for name in ("partials/dropdown_menu_v1.html","surveys/student_survey_comparison.html","surveys/student_reconciliation_source.html"): env.get_template(name)

def clear_cache():
 for cache in (PROJECT/"app").rglob("__pycache__"):
  if cache.is_dir(): shutil.rmtree(cache,ignore_errors=True)

def runtime_check():
 r=subprocess.run([sys.executable,"-c",RUNTIME_SCRIPT],cwd=str(PROJECT),capture_output=True,text=True,timeout=90)
 out=(r.stdout or "")+(r.stderr or "")
 if r.returncode!=0: raise RuntimeError("Runtime route check lỗi:\n"+out[-6000:])
 return out.strip()

def verify_database():
 c=sqlite3.connect(str(DB))
 try:
  integrity=c.execute("PRAGMA integrity_check").fetchone()[0]; fk=c.execute("PRAGMA foreign_key_check").fetchall(); counts={}
  for table in ("student_reconciliation_source_states","student_reconciliation_import_logs","student_reconciliation_state_enrollments"):
   if not c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",(table,)).fetchone(): raise RuntimeError(f"Thiếu bảng V12: {table}")
   counts[table]=int(c.execute(f'SELECT COUNT(*) FROM "{table}"').fetchone()[0])
  if integrity!="ok" or fk: raise RuntimeError(f"DB hậu kiểm không đạt: integrity={integrity}, FK={len(fk)}")
  return str(integrity),len(fk),counts
 finally: c.close()

def main():
 print("="*112); print("V12 CHÍNH THỨC - NẠP NGUỒN HỌC SINH ĐỐI CHIẾU THEO XÃ/PHƯỜNG"); print("="*112)
 manifest=[]
 try:
  print("[1/8] Kiểm tra source + database..."); preflight_source()
  print("[2/8] Backup database..."); backup_database(); print("      ",DB_BACKUP)
  print("[3/8] Backup mã nguồn..."); manifest=backup_files(); print("      ",FILE_BACKUP)
  print("[4/8] Ghi V12 source/template..."); write_payloads()
  print("[5/8] Tạo schema quản lý nguồn đối chiếu..."); migrate_database()
  print("[6/8] Compile + kiểm Jinja..."); verify_source_syntax(); clear_cache()
  print("[7/8] Import app.main + kiểm route..."); runtime=runtime_check(); print("      ",runtime.splitlines()[-1] if runtime else "PASS")
  print("[8/8] Hậu kiểm database..."); integrity,fk_count,counts=verify_database()
  EXPORTS.mkdir(parents=True,exist_ok=True)
  REPORT.write_text(REPORT_TEMPLATE.format(STAMP=STAMP,DB_BACKUP=DB_BACKUP,FILE_BACKUP=FILE_BACKUP,integrity=integrity,fk_count=fk_count,counts=counts),encoding="utf-8")
  print(); print("="*112); print("CÀI V12 THÀNH CÔNG"); print("="*112)
  print(f"Integrity: {integrity}"); print(f"FK errors: {fk_count}"); print("Nguồn học sinh đã nạp: KHÔNG (sẽ nạp trên giao diện theo xã/phường)")
  print("Menu mới: 2.5.0. Nạp nguồn học sinh theo xã/phường"); print(f"BACKUP DB: {DB_BACKUP}"); print(f"BACKUP SOURCE: {FILE_BACKUP}"); print(f"REPORT: {REPORT}")
  print("KHỞI ĐỘNG LẠI PHẦN MỀM RỒI KIỂM TRA 2.5.0."); return 0
 except Exception as exc:
  print(); print("CÓ LỖI V12:",repr(exc)); print("Đang khôi phục...")
  try:
   if manifest: restore_files(manifest)
  except Exception as e: print("Lỗi khôi phục source:",repr(e))
  try: restore_database()
  except Exception as e: print("Lỗi khôi phục DB:",repr(e))
  print("V12 KHÔNG ĐƯỢC CÀI. Đã hoàn tác theo backup nếu có."); return 2

if __name__=="__main__": raise SystemExit(main())
